<?php
require_once __DIR__ . '/../config/auth.php';
require_admin();
require_once __DIR__ . '/../includes/promotions.php';
require_once __DIR__ . '/../includes/notifications.php';
require_once __DIR__ . '/../includes/product-categories.php';
$pdo=db(); if ($pdo) { try { ensure_rosa_product_categories($pdo); } catch (Throwable $e) {} } $pageTitle='Promo & Voucher'; require_once __DIR__ . '/_header.php';
if(!$pdo){echo '<div class="admin-alert error">Database belum terhubung.</div>'; require __DIR__.'/_footer.php'; exit;}
ensure_promotions_tables($pdo);
if(empty($_SESSION['admin_csrf'])) $_SESSION['admin_csrf']=bin2hex(random_bytes(32)); $csrf=$_SESSION['admin_csrf'];
$action=$_POST['action']??'';
if($_SERVER['REQUEST_METHOD']==='POST'){
  try{
    if(!hash_equals($csrf,$_POST['csrf']??'')) throw new RuntimeException('Sesi keamanan tidak valid.');
    if($action==='delete'){
      $kind=$_POST['kind']==='voucher'?'voucher':'promotion'; $id=(int)$_POST['id'];
      $table=$kind==='voucher'?'vouchers':'promotions'; $st=$pdo->prepare("DELETE FROM {$table} WHERE id=?"); $st->execute([$id]);
      admin_flash('success',ucfirst($kind).' berhasil dihapus.');
    } else {
      $kind=$_POST['kind']==='voucher'?'voucher':'promotion'; $id=(int)($_POST['id']??0); $name=trim($_POST['name']??''); $description=trim($_POST['description']??''); $type=$_POST['discount_type']==='fixed'?'fixed':'percent'; $value=(float)$_POST['discount_value']; $min=(float)$_POST['min_order']; $max=trim($_POST['max_discount']??'')===''?null:(float)$_POST['max_discount']; $scope=in_array($_POST['scope_type']??'all',['all','category','product'],true)?$_POST['scope_type']:'all'; $scopeVal=trim($_POST['scope_value']??'')?:null; $member=isset($_POST['member_only'])?1:0; $quota=trim($_POST['quota']??'')===''?null:max(1,(int)$_POST['quota']); $start=str_replace('T',' ',trim($_POST['starts_at']??'')); $end=str_replace('T',' ',trim($_POST['ends_at']??'')); $status=$_POST['status']==='inactive'?'inactive':'active';
      if($name==='') throw new RuntimeException('Nama wajib diisi.'); if($value<=0) throw new RuntimeException('Nilai diskon harus lebih dari 0.'); if(strtotime($start)===false||strtotime($end)===false||strtotime($end)<=strtotime($start)) throw new RuntimeException('Tanggal mulai/berakhir tidak valid.'); if($scope!=='all'&&$scopeVal===null) throw new RuntimeException('Isi target kategori atau ID produk.');
      if($scope==='category' && !in_array($scopeVal, rosa_product_categories(), true)) throw new RuntimeException('Kategori promo tidak valid. Pilih kategori produk yang tersedia.');
      if($kind==='voucher'){
        $code=strtoupper(preg_replace('/[^A-Za-z0-9_-]/','',trim($_POST['code']??''))); if($code==='') throw new RuntimeException('Kode voucher wajib diisi.');
        if($id){$st=$pdo->prepare('UPDATE vouchers SET code=?,name=?,description=?,discount_type=?,discount_value=?,min_order=?,max_discount=?,scope_type=?,scope_value=?,member_only=?,quota=?,starts_at=?,ends_at=?,status=? WHERE id=?');$st->execute([$code,$name,$description,$type,$value,$min,$max,$scope,$scopeVal,$member,$quota,$start,$end,$status,$id]);}
        else {$st=$pdo->prepare('INSERT INTO vouchers (code,name,description,discount_type,discount_value,min_order,max_discount,scope_type,scope_value,member_only,quota,starts_at,ends_at,status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute([$code,$name,$description,$type,$value,$min,$max,$scope,$scopeVal,$member,$quota,$start,$end,$status]); $newId=(int)$pdo->lastInsertId(); if($status==='active'){ try { member_notification_broadcast($pdo, 'voucher', 'Voucher baru tersedia 🎟️', $name.' tersedia dengan kode '.$code.'. '.($description!==''?$description:'Gunakan voucher ini saat checkout.'), page_url('promo.php')); } catch(Throwable $e) {} }}
      } else {
        if($id){$st=$pdo->prepare('UPDATE promotions SET name=?,description=?,discount_type=?,discount_value=?,min_order=?,max_discount=?,scope_type=?,scope_value=?,member_only=?,quota=?,starts_at=?,ends_at=?,status=? WHERE id=?');$st->execute([$name,$description,$type,$value,$min,$max,$scope,$scopeVal,$member,$quota,$start,$end,$status,$id]);}
        else {$st=$pdo->prepare('INSERT INTO promotions (name,description,discount_type,discount_value,min_order,max_discount,scope_type,scope_value,member_only,quota,starts_at,ends_at,status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute([$name,$description,$type,$value,$min,$max,$scope,$scopeVal,$member,$quota,$start,$end,$status]); if($status==='active'){ try { member_notification_broadcast($pdo, 'promo', 'Promo baru tersedia 🎉', $name.'. '.($description!==''?$description:'Ada promo baru yang bisa Anda nikmati sebagai Member.'), page_url('promo.php')); } catch(Throwable $e) {} }}
      }
      admin_flash('success',ucfirst($kind).' berhasil disimpan.');
    }
    header('Location: '.page_url('admin/promo.php')); exit;
  }catch(Throwable $e){admin_flash('error',$e->getMessage()); header('Location: '.page_url('admin/promo.php')); exit;}
}
$promos=$pdo->query('SELECT * FROM promotions ORDER BY starts_at DESC,id DESC')->fetchAll(); $vouchers=$pdo->query('SELECT * FROM vouchers ORDER BY starts_at DESC,id DESC')->fetchAll(); $cats=array_map(static fn($name) => ['name'=>$name], rosa_product_categories()); $prods=$pdo->query('SELECT id,name FROM products WHERE status=\'active\' ORDER BY name')->fetchAll();
function admin_datetime_local($v){return date('Y-m-d\TH:i',strtotime($v));}
$editKind = $_GET['kind'] ?? ''; $editId = (int)($_GET['id'] ?? 0); $editData = null; if ($editId && in_array($editKind,['promotion','voucher'],true)) { $tbl=$editKind==='voucher'?'vouchers':'promotions'; $es=$pdo->prepare("SELECT * FROM {$tbl} WHERE id=? LIMIT 1"); $es->execute([$editId]); $editData=$es->fetch() ?: null; }
?>
<div class="admin-title"><div><h1>Promo & Voucher</h1><p style="color:#777;margin:7px 0 0">Buat promo otomatis dan kode voucher khusus Member.</p></div></div>
<div class="admin-card promo-admin-form"><h2><?php echo $editData ? 'Edit Promo / Voucher' : 'Tambah Promo / Voucher'; ?></h2><p class="promo-admin-help">Promo tanpa kode diterapkan otomatis. Voucher menggunakan kode yang diketik customer di checkout. Keduanya bisa dibatasi hanya Member.</p>
<form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?php echo htmlspecialchars($csrf); ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?php echo (int)$editId; ?>">
<div class="admin-grid-2"><label class="admin-field">Jenis<select name="kind" id="promoKind"><option value="promotion" <?php echo ($editKind!=='voucher')?'selected':''; ?>>Promo otomatis</option><option value="voucher" <?php echo $editKind==='voucher'?'selected':''; ?>>Voucher kode</option></select></label><label class="admin-field">Nama<input name="name" required placeholder="Contoh: Promo Member Agustus" value="<?php echo htmlspecialchars($editData['name'] ?? "", ENT_QUOTES); ?>"></label></div>
<div class="admin-grid-2" id="voucherCodeWrap"><label class="admin-field">Kode Voucher<input name="code" maxlength="60" placeholder="Contoh: MEMBER10" value="<?php echo htmlspecialchars($editData['code'] ?? "", ENT_QUOTES); ?>"></label><label class="admin-field">Jenis Diskon<select name="discount_type"><option value="percent" <?php echo (($editData['discount_type'] ?? 'percent')==='percent')?'selected':''; ?>>Persentase (%)</option><option value="fixed" <?php echo (($editData['discount_type'] ?? 'percent')==='fixed')?'selected':''; ?>>Nominal (Rp)</option></select></label></div>
<div class="admin-grid-2"><label class="admin-field">Nilai Diskon<input type="number" name="discount_value" min="1" step="0.01" required placeholder="10" value="<?php echo htmlspecialchars((string)($editData['discount_value'] ?? ''), ENT_QUOTES); ?>"></label><label class="admin-field">Minimum Belanja<input type="number" name="min_order" min="0" step="1" value="<?php echo htmlspecialchars((string)($editData['min_order'] ?? '0'), ENT_QUOTES); ?>"></label></div>
<div class="admin-grid-2"><label class="admin-field">Maksimal Diskon (opsional)<input type="number" name="max_discount" min="0" step="1" placeholder="Kosongkan jika tidak ada batas" value="<?php echo htmlspecialchars((string)($editData['max_discount'] ?? ''), ENT_QUOTES); ?>"></label><label class="admin-field">Kuota (opsional)<input type="number" name="quota" min="1" step="1" placeholder="Kosongkan = tidak terbatas" value="<?php echo htmlspecialchars((string)($editData['quota'] ?? ''), ENT_QUOTES); ?>"></label></div>
<div class="admin-grid-2"><label class="admin-field">Berlaku Mulai<input type="datetime-local" name="starts_at" required value="<?php echo htmlspecialchars(admin_datetime_local($editData['starts_at'] ?? date('Y-m-d H:i:s')), ENT_QUOTES); ?>"></label><label class="admin-field">Berlaku Sampai<input type="datetime-local" name="ends_at" required value="<?php echo htmlspecialchars(admin_datetime_local($editData['ends_at'] ?? date('Y-m-d H:i:s',time()+7*86400)), ENT_QUOTES); ?>"></label></div>
<div class="admin-grid-2"><label class="admin-field">Target Produk<select name="scope_type" id="scopeType"><option value="all" <?php echo (($editData['scope_type'] ?? 'all')==='all')?'selected':''; ?>>Semua Produk</option><option value="category" <?php echo (($editData['scope_type'] ?? 'all')==='category')?'selected':''; ?>>Kategori</option><option value="product" <?php echo (($editData['scope_type'] ?? 'all')==='product')?'selected':''; ?>>Produk tertentu</option></select></label><label class="admin-field" id="scopeValueWrap">Target<select name="scope_value" id="scopeValue"><option value="">Pilih target</option><?php foreach($cats as $c): ?><option data-type="category" value="<?php echo htmlspecialchars($c['name']); ?>" <?php echo (($editData['scope_value'] ?? '')===$c['name'])?'selected':''; ?>><?php echo htmlspecialchars($c['name']); ?></option><?php endforeach; ?><?php foreach($prods as $p): ?><option data-type="product" value="<?php echo htmlspecialchars($p['id']); ?>" <?php echo (($editData['scope_value'] ?? '')===$p['id'])?'selected':''; ?>><?php echo htmlspecialchars($p['name']); ?> (<?php echo htmlspecialchars($p['id']); ?>)</option><?php endforeach; ?></select></label></div>
<div class="admin-grid-2"><label class="admin-check"><input type="checkbox" name="member_only" <?php echo (!isset($editData['member_only']) || (int)$editData['member_only']===1)?'checked':''; ?>> Khusus Member</label><label class="admin-field">Status<select name="status"><option value="active" <?php echo (($editData['status'] ?? 'active')==='active')?'selected':''; ?>>Aktif</option><option value="inactive" <?php echo (($editData['status'] ?? 'active')==='inactive')?'selected':''; ?>>Nonaktif</option></select></label></div>
<label class="admin-field">Deskripsi<textarea name="description" rows="3" placeholder="Contoh: Diskon khusus Member untuk pembelian bulan ini."><?php echo htmlspecialchars($editData['description'] ?? '', ENT_QUOTES); ?></textarea></label>
<button class="admin-btn" type="submit"><i class="bi bi-save"></i> <?php echo $editData ? 'Simpan Perubahan' : 'Simpan Promo'; ?></button></form></div>
<div class="admin-card promo-admin-list"><h2>Promo Otomatis</h2><?php if(!$promos): ?><p class="promo-admin-empty">Belum ada promo.</p><?php else: ?><div class="promo-admin-table-wrap"><table class="admin-table"><thead><tr><th>Nama</th><th>Diskon</th><th>Target</th><th>Member</th><th>Masa Berlaku</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($promos as $r): ?><tr><td><strong><?php echo htmlspecialchars($r['name']); ?></strong><small><?php echo htmlspecialchars($r['description']??''); ?></small></td><td><?php echo htmlspecialchars(promo_label($r)); ?><small>Min Rp<?php echo number_format((float)$r['min_order'],0,',','.'); ?></small></td><td><?php echo htmlspecialchars(promo_scope_label($r)); ?></td><td><?php echo (int)$r['member_only']?'Ya':'Semua'; ?></td><td><?php echo promo_format_date($r['starts_at']); ?> - <?php echo promo_format_date($r['ends_at']); ?></td><td><?php echo htmlspecialchars($r['status']); ?><small><?php echo (int)$r['usage_count']; ?> terpakai</small></td><td><a class="admin-btn secondary" href="<?php echo page_url('admin/promo.php?kind=promotion&id='.(int)$r['id']); ?>">Edit</a> <form style="display:inline" method="post" onsubmit="return confirm('Hapus promo ini?')"><input type="hidden" name="csrf" value="<?php echo htmlspecialchars($csrf); ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="kind" value="promotion"><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><button class="admin-btn danger" type="submit">Hapus</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
<div class="admin-card promo-admin-list"><h2>Voucher</h2><?php if(!$vouchers): ?><p class="promo-admin-empty">Belum ada voucher.</p><?php else: ?><div class="promo-admin-table-wrap"><table class="admin-table"><thead><tr><th>Kode</th><th>Nama</th><th>Diskon</th><th>Target</th><th>Member</th><th>Masa Berlaku</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($vouchers as $r): ?><tr><td><strong class="promo-code-admin"><?php echo htmlspecialchars($r['code']); ?></strong></td><td><?php echo htmlspecialchars($r['name']); ?></td><td><?php echo htmlspecialchars(promo_label($r)); ?><small>Min Rp<?php echo number_format((float)$r['min_order'],0,',','.'); ?></small></td><td><?php echo htmlspecialchars(promo_scope_label($r)); ?></td><td><?php echo (int)$r['member_only']?'Ya':'Semua'; ?></td><td><?php echo promo_format_date($r['starts_at']); ?> - <?php echo promo_format_date($r['ends_at']); ?></td><td><?php echo htmlspecialchars($r['status']); ?><small><?php echo (int)$r['usage_count']; ?> terpakai</small></td><td><a class="admin-btn secondary" href="<?php echo page_url('admin/promo.php?kind=voucher&id='.(int)$r['id']); ?>">Edit</a> <form style="display:inline" method="post" onsubmit="return confirm('Hapus voucher ini?')"><input type="hidden" name="csrf" value="<?php echo htmlspecialchars($csrf); ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="kind" value="voucher"><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><button class="admin-btn danger" type="submit">Hapus</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
<style>.promo-admin-form h2,.promo-admin-list h2{margin:0 0 7px;color:#18243a}.promo-admin-help,.promo-admin-empty{color:#7f747d;font-size:13px}.promo-admin-list{margin-top:18px}.promo-admin-table-wrap{overflow:auto}.promo-admin-table-wrap .admin-table{min-width:980px}.promo-admin-table-wrap td small{display:block;color:#948990;font-size:11px;margin-top:4px}.promo-code-admin{color:#d64a8a;letter-spacing:1px}.promo-admin-form .admin-check{margin-top:30px}</style>
<script>
(function(){const kind=document.getElementById('promoKind'),code=document.getElementById('voucherCodeWrap'),scope=document.getElementById('scopeType'),value=document.getElementById('scopeValue');function refresh(){code.style.display=kind.value==='voucher'?'grid':'none';Array.from(value.options).forEach(o=>{if(!o.value)return;o.hidden=scope.value!=='all'&&o.dataset.type!==scope.value;o.style.display=o.hidden?'none':'';});if(scope.value==='all'){value.value='';value.disabled=true;}else value.disabled=false;}kind.addEventListener('change',refresh);scope.addEventListener('change',refresh);refresh();})();
</script>
